import {
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const seoAppDir = path.join(rootDir, "src", "app", "(seo)");
const localizedSeoAppDir = path.join(rootDir, "src", "app", "[locale]", "(seo)");
const pageFileName = "page.tsx";
const generatedMarker =
  "// AUTO-GENERATED by scripts/generate-localized-seo-pages.mjs. Do not edit manually.";

function collectPageFiles(dir) {
  const entries = readdirSync(dir, { withFileTypes: true }).sort((left, right) =>
    left.name.localeCompare(right.name),
  );
  const files = [];

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      files.push(...collectPageFiles(fullPath));
      continue;
    }

    if (entry.isFile() && entry.name === pageFileName) {
      files.push(fullPath);
    }
  }

  return files;
}

function toPosixPath(value) {
  return value.split(path.sep).join("/");
}

function toRoutePath(baseFilePath) {
  const relativePath = path.relative(seoAppDir, path.dirname(baseFilePath));
  return relativePath ? `/${toPosixPath(relativePath)}` : "/";
}

function toImportPath(baseFilePath) {
  const relativePath = path.relative(seoAppDir, baseFilePath).replace(/\.tsx$/, "");
  return `@/app/(seo)/${toPosixPath(relativePath)}`;
}

function toComponentName(routePath) {
  const segments = routePath
    .split("/")
    .filter(Boolean)
    .flatMap((segment) => segment.split(/[^a-zA-Z0-9]+/))
    .filter(Boolean)
    .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1));

  return `Localized${segments.join("") || "Seo"}Page`;
}

function buildFileContents(baseFilePath) {
  const routePath = toRoutePath(baseFilePath);
  const importPath = toImportPath(baseFilePath);
  const componentName = toComponentName(routePath);

  return `${generatedMarker}

import SeoPage, { metadata as baseMetadata } from "${importPath}";
import {
  generateLocalizedPageMetadataForPath,
  type LocalePageParams,
} from "@/lib/localized-page";

export const runtime = "edge";

export async function generateMetadata({ params }: LocalePageParams) {
  return generateLocalizedPageMetadataForPath(params, "${routePath}", baseMetadata);
}

export default function ${componentName}() {
  return <SeoPage />;
}
`;
}

function isGeneratedFile(filePath) {
  try {
    return readFileSync(filePath, "utf8").startsWith(generatedMarker);
  } catch {
    return false;
  }
}

function removeEmptyDirectories(dir) {
  if (dir === localizedSeoAppDir) {
    return;
  }

  const entries = readdirSync(dir, { withFileTypes: true });
  if (entries.length > 0) {
    return;
  }

  rmSync(dir, { recursive: true, force: true });
  removeEmptyDirectories(path.dirname(dir));
}

const basePageFiles = collectPageFiles(seoAppDir);
const localizedPageFiles = collectPageFiles(localizedSeoAppDir);
const expectedGeneratedFiles = new Set();

let createdCount = 0;
let updatedCount = 0;
let removedCount = 0;
let preservedManualCount = 0;

for (const baseFilePath of basePageFiles) {
  const relativePath = path.relative(seoAppDir, baseFilePath);
  const localizedFilePath = path.join(localizedSeoAppDir, relativePath);
  const nextContents = buildFileContents(baseFilePath);

  expectedGeneratedFiles.add(localizedFilePath);

  if (isGeneratedFile(localizedFilePath)) {
    const currentContents = readFileSync(localizedFilePath, "utf8");
    if (currentContents !== nextContents) {
      writeFileSync(localizedFilePath, nextContents);
      updatedCount += 1;
    }
    continue;
  }

  try {
    readFileSync(localizedFilePath, "utf8");
    preservedManualCount += 1;
    continue;
  } catch {
    mkdirSync(path.dirname(localizedFilePath), { recursive: true });
    writeFileSync(localizedFilePath, nextContents);
    createdCount += 1;
  }
}

for (const localizedFilePath of localizedPageFiles) {
  if (!isGeneratedFile(localizedFilePath)) {
    continue;
  }

  if (expectedGeneratedFiles.has(localizedFilePath)) {
    continue;
  }

  rmSync(localizedFilePath, { force: true });
  removeEmptyDirectories(path.dirname(localizedFilePath));
  removedCount += 1;
}

console.log(
  [
    `Localized SEO page sync complete.`,
    `base=${basePageFiles.length}`,
    `created=${createdCount}`,
    `updated=${updatedCount}`,
    `removed=${removedCount}`,
    `manual=${preservedManualCount}`,
  ].join(" "),
);
